// O dispatch responder 200 so quer dizer que entrou na fila. O que
// interessa e como o run terminou, 70 min depois — a noite boa leva ~20 min,
// mas o job espera pela HG e pelo Kuma quando eles falham, e o YAML corta em
// 60. Esperar menos que o timeout do job faz o alarme gritar por um run que
// ainda ia dar certo.
const runs = $input.first().json.workflow_runs || [];

if (!runs.length) {
  return [{ json: {
    ok: false,
    motivo: 'O disparo foi aceito mas nenhum run apareceu no GitHub.',
    url: 'https://github.com/DaniBatista04/midia-vertical/actions/workflows/clima-diario.yml',
  } }];
}

const run = runs[0];
const ok = run.status === 'completed' && run.conclusion === 'success';

let motivo = '';
if (run.status !== 'completed') {
  motivo = `O run ainda esta em "${run.status}" 70 min depois — passou do timeout de 60 min do job.`;
} else if (!ok) {
  motivo = `O run terminou em "${run.conclusion}".`;
}

return [{ json: { ok, motivo, url: run.html_url, run: run.id, criado: run.created_at } }];

// O que a rota respondeu, para o alarme citar em vez de mandar procurar.
// Sem isto o aviso era fixo — falava de CRON_SECRET e do deploy — e a noite
// de 31/08/2026 custou a manha seguinte: a rota tinha respondido 401 com o
// motivo no corpo, e nada disso chegava a mensagem.
const j = $input.first().json || {};

// A forma do item de erro do no HTTP Request muda entre versoes do n8n, e o
// corpo da resposta as vezes vem em `error`, as vezes solto. Procura nos dois.
const e = j.error || {};
const status = e.httpCode ?? e.statusCode ?? e.status ?? j.statusCode ?? '?';

// O corpo interessa mais que a mensagem: e nele que a rota escreve o motivo.
const cru = e.description ?? e.raw ?? e.body ?? j.body ?? e.message ?? j.message ?? j;
const texto = typeof cru === 'string' ? cru : JSON.stringify(cru);

// O 401 tem tres formas, a rota diz qual foi, e cada uma pede conserto num
// campo diferente da credencial. Seguir so o status mandaria mexer no valor do
// token quando o problema e o nome do cabecalho — foi o passo perdido em
// 01/09/2026. As duas grafias existem porque o corpo pode chegar sem acento.
function ondeNo401(t) {
  if (/sem cabe[cç]alho/i.test(t)) {
    return 'NAO chegou cabecalho Authorization nenhum — o valor do token nao tem nada a ver com isto. '
      + 'No no "Dispara o clima": ou nao ha credencial escolhida, ou a escolhida manda outro cabecalho. '
      + 'Leia o NOME dela — tem de ser "Clima - CLIMA_DISPATCH_TOKEN". A vizinha na lista, '
      + '"Webhook-MURAL-Auth", usa outro cabecalho, e por isso nada chega. Dentro da credencial, o campo '
      + 'Name tem de ser exatamente "Authorization".';
  }
  if (/n[ãa]o come[çc]a com/i.test(t)) {
    return 'O cabecalho Authorization chegou, mas sem o prefixo. Na credencial, o campo Value tem de ser '
      + '"Bearer <token>" — o "Bearer " e o espaco fazem parte do valor, porque a rota le so o que vem depois.';
  }
  return 'O cabecalho e o prefixo estao certos; o token e que nao bate. Nao da para comparar com a Vercel '
    + '(la a variavel e Sensitive, write-only), entao gire: token novo na Vercel (Production) e o mesmo '
    + 'valor na credencial, com "Bearer " na frente. Girar dispensa saber o valor antigo.';
}

let onde;
if (String(status) === '401') onde = ondeNo401(texto);
else if (String(status) === '503') onde = 'GITHUB_DISPATCH_TOKEN nao esta no projeto da Vercel.';
else if (String(status) === '502') onde = 'A rota chamou o GitHub e ele recusou o dispatch — o texto acima e a resposta dele. Costuma ser o token expirado ou sem permissao de Actions.';
else onde = 'Nem chegou resposta HTTP: a rota caiu ou o n8n nao alcancou o dominio.';

return [{ json: { status, corpo: String(texto).slice(0, 300), onde } }];
